const fs = require('fs');
const crypto = require('crypto');

// Récupérer le message de l'AI Agent
const message = $input.first().json.output;

// Vérifier si le message contient AUTH
if (!message.includes('AUTH:')) {
  return [{ json: { authenticated: false, reason: 'Pas de tentative de login' } }];
}

// Extraire username et password
const parts = message.split('AUTH:')[1].split(':');
const username = parts[0];
const password = parts[1];

// Hasher le mot de passe
const passwordHash = crypto
  .createHash('sha256')
  .update(password)
  .digest('hex');

// Lire le fichier utilisateur
const filePath = `/home/aichath/Tek2/G-AIA-410-COT-4-1-persona-22/persona/users/${username}.json`;
if (!fs.existsSync(filePath)) {
  return [{ json: { authenticated: false, reason: 'Utilisateur introuvable' } }];
}

const user = JSON.parse(fs.readFileSync(filePath, 'utf8'));

// Vérifier le mot de passe
if (user.password_hash !== passwordHash) {
  return [{ json: { authenticated: false, reason: 'Mot de passe incorrect' } }];
}

// Succès
return [{ json: { authenticated: true, user: user } }];

const articles = $input.first().json.articles;
const user = $('Code in JavaScript').item.json.user;
const interests = user.interests.join(', ');

const articlesText = articles.map((a, i) => 
  `Article ${i+1}:
  Titre: ${a.title}
  Description: ${a.description}
  URL: ${a.url}
  Source: ${a.source.name}`
).join('\n\n');

const prompt = `Tu es un assistant de curation de news.
L'utilisateur s'intéresse à : ${interests}

Voici les articles disponibles :
${articlesText}

Pour chaque article pertinent :
1. Donne un résumé de 2-3 phrases en français
2. Indique pourquoi il correspond aux intérêts de l'utilisateur
3. Garde l'URL

Réponds en JSON avec ce format :
{
  "articles": [
    {
      "titre": "...",
      "resume": "...",
      "url": "...",
      "source": "...",
      "pertinence": "..."
    }
  ]
}`;

return [{ json: { prompt: prompt, user: user } }];

const geminiResponse = $input.first().json.candidates[0].content.parts[0].text;
const user = $('Code in JavaScript1').first().json.user;

// Nettoyer la réponse JSON
const cleanJson = geminiResponse
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .replace(/\\n/g, '')
  .trim();

let data;
try {
  data = JSON.parse(cleanJson);
} catch(e) {
  // Gemini n'a pas répondu en JSON, on crée un article par défaut
  data = {
    articles: [{
      titre: "Actualités du jour",
      resume: geminiResponse,
      url: "#",
      source: "Persona AI"
    }]
  };
}
const articles = data.articles;

// Construire le HTML de l'email
let articlesHtml = '';
articles.forEach((article, i) => {
  articlesHtml += `
    <div style="margin-bottom:30px; padding:20px; border-left:4px solid #E8420A; background:#f9f9f9;">
      <h3 style="color:#1A3A6B; margin:0 0 10px 0;">${i+1}. ${article.titre}</h3>
      <p style="color:#444; line-height:1.6;">${article.resume}</p>
      <p style="color:#666; font-size:13px;"><strong>Source :</strong> ${article.source}</p>
      <a href="${article.url}" style="color:#E8420A; font-weight:bold;">Lire l article complet</a>
    </div>
  `;
});

const html = `<!DOCTYPE html>
<html>
<head><meta charset="UTF-8"></head>
<body style="font-family:Arial,sans-serif; max-width:600px; margin:0 auto; padding:20px;">
  <div style="background:#1A3A6B; padding:30px; text-align:center; border-radius:8px 8px 0 0;">
    <h1 style="color:white; margin:0;">Ta Newsletter Personnalisee</h1>
    <p style="color:#FFD6A5; margin:10px 0 0 0;">Bonjour ${user.username} ! Voici tes news du jour.</p>
  </div>
  <div style="padding:20px; background:white;">
    <p style="color:#666;">Centres d interet : <strong>${user.interests.join(', ')}</strong></p>
    <hr style="border:1px solid #eee;">
    ${articlesHtml}
  </div>
  <div style="background:#f0f0f0; padding:15px; text-align:center; border-radius:0 0 8px 8px;">
    <p style="color:#999; font-size:12px;">Newsletter generee par Persona - Epitech Benin</p>
